'use strict';

const http = require('http');
const https = require('https');
const { URL } = require('url');

/**
 * Fires the webhook once. Resolves with { status } on response;
 * rejects on network error or timeout.
 */
async function send(event, url, { timeoutMs = 5000 } = {}) {
  const u = new URL(url);
  const mod = u.protocol === 'https:' ? https : http;
  return new Promise((resolve, reject) => {
    const req = mod.request(u, { method: 'POST', headers: { 'Content-Type': 'application/json' } }, (res) => {
      res.resume();
      resolve({ status: res.statusCode });
    });
    req.setTimeout(timeoutMs, () => { req.destroy(new Error('timeout')); });
    req.on('error', reject);
    req.write(JSON.stringify(event));
    req.end();
  });
}

// TODO: implement sendWithRetries(event, url, opts)
async function sendWithRetries(event, url, opts = {}) {
  // PLACEHOLDER — replace with real retry logic.
  try {
    const r = await send(event, url, opts);
    return { ok: r.status >= 200 && r.status < 300, attempts: 1, last_status: r.status, last_error: null, attempts_log: [] };
  } catch (e) {
    return { ok: false, attempts: 1, last_status: null, last_error: e.message, attempts_log: [] };
  }
}

module.exports = { send, sendWithRetries };

