'use strict';

const http = require('http');
const https = require('https');
const { URL } = require('url');

async function send(event, url, { timeoutMs = 5000 } = {}) {
  const u = new URL(url);
  const mod = u.protocol === 'https:' ? https : http;
  return new Promise((resolve, reject) => {
    const req = mod.request(u, { method: 'POST', headers: { 'Content-Type': 'application/json' } }, (res) => {
      res.resume();
      resolve({ status: res.statusCode });
    });
    req.setTimeout(timeoutMs, () => { req.destroy(new Error('timeout')); });
    req.on('error', reject);
    req.write(JSON.stringify(event));
    req.end();
  });
}

const BACKOFF_BASE_MS = [1000, 2000, 4000, 8000];
const MAX_ATTEMPTS = 4;
const JITTER = 0.25;

function wait(ms) { return new Promise(r => setTimeout(r, ms)); }
function jittered(base) { return Math.round(base * (1 + (Math.random() * 2 - 1) * JITTER)); }

async function sendWithRetries(event, url, opts = {}) {
  const attempts_log = [];
  let lastStatus = null;
  let lastError = null;

  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    let status = null;
    let error = null;
    try {
      const r = await send(event, url, { timeoutMs: 5000 });
      status = r.status;
    } catch (e) {
      error = e.message || String(e);
    }
    attempts_log.push({ attempt, status, error });
    lastStatus = status;
    lastError = error;

    if (status && status >= 200 && status < 300) {
      return { ok: true, attempts: attempt, last_status: status, last_error: null, attempts_log };
    }
    if (status && status >= 400 && status < 500) {
      // Don't retry on 4xx — receiver said don't bother.
      return { ok: false, attempts: attempt, last_status: status, last_error: null, attempts_log };
    }
    if (attempt < MAX_ATTEMPTS) {
      await wait(jittered(BACKOFF_BASE_MS[attempt - 1]));
    }
  }
  return { ok: false, attempts: MAX_ATTEMPTS, last_status: lastStatus, last_error: lastError, attempts_log };
}

module.exports = { send, sendWithRetries };

