cat > tests/retry.test.js <<'EOF'
const nock = require('nock');
const { sendWithRetries } = require('../lib/webhookSender');

afterEach(() => nock.cleanAll());

test('retries to success on 503 then 200', async () => {
  nock('http://x.com').post('/h').reply(503).post('/h').reply(200);
  const r = await sendWithRetries({a:1}, 'http://x.com/h');
  expect(r.ok).toBe(true);
  expect(r.attempts).toBe(2);
  expect(r.last_status).toBe(200);
}, 30000);

test('does NOT retry on 400', async () => {
  nock('http://x.com').post('/h').reply(400);
  const r = await sendWithRetries({a:1}, 'http://x.com/h');
  expect(r.ok).toBe(false);
  expect(r.attempts).toBe(1);
  expect(r.last_status).toBe(400);
}, 10000);

test('returns ok=false after 4 persistent 500s', async () => {
  nock('http://x.com').post('/h').times(4).reply(500);
  const r = await sendWithRetries({a:1}, 'http://x.com/h');
  expect(r.ok).toBe(false);
  expect(r.attempts).toBe(4);
  expect(r.last_status).toBe(500);
  expect(r.attempts_log.length).toBe(4);
}, 30000);
EOF
